<script setup lang="ts">
import { ref, onUnmounted } from 'vue'
import { useI18n } from 'vue-i18n'
import { api, json } from '../api'
import type { JobStatus } from '../types'
import { useApp } from '../stores/app'
import Icon from './Icon.vue'
const props = defineProps<{ ids?: string[]; filters?: Record<string, string> }>(); const emit = defineEmits<{ close: [] }>(); const { t, locale } = useI18n(); const app = useApp()
const scope = ref(props.ids?.length ? 'selected' : 'all'); const format = ref('xlsx'); const busy = ref(false); const job = ref<JobStatus>(); let timer: ReturnType<typeof setTimeout> | undefined
async function poll(id: string) { try { job.value = await api<JobStatus>(`/jobs/${id}`); if (['pending','running'].includes(job.value.status)) timer = setTimeout(() => poll(id), 800) } catch (e) { app.report(e); busy.value = false } }
async function start() { busy.value = true; app.clear(); try { job.value = await api<JobStatus>('/exports', json('POST', { ids: scope.value === 'selected' ? props.ids : [], filters: props.filters || {}, format: format.value, locale: locale.value })); await poll(job.value.id) } catch (e) { app.report(e); busy.value = false } }
onUnmounted(() => clearTimeout(timer))
</script>
<template><Teleport to="body"><div class="modal-backdrop" @click.self="emit('close')"><section class="modal" role="dialog" aria-modal="true" :aria-label="t('exportTitle')"><button class="icon-btn modal-close" :aria-label="t('close')" @click="emit('close')"><Icon name="close" /></button><span class="modal-symbol"><Icon name="download" :size="26" /></span><h2>{{ t('exportTitle') }}</h2><p class="muted">{{ t('exportScope') }}</p><template v-if="!job"><div class="field"><label>{{ t('export') }}</label><select v-model="scope"><option v-if="ids?.length" value="selected">{{ t('selectedProducts') }} ({{ ids.length }})</option><option value="all">{{ t('matchingProducts') }}</option></select></div><div class="format-options"><button class="format-card" :class="{ chosen: format === 'xlsx' }" @click="format = 'xlsx'"><Icon name="file" /><strong>{{ t('workbook') }}</strong><small>{{ t('fiveSheets') }}</small></button><button class="format-card" :class="{ chosen: format === 'csv' }" @click="format = 'csv'"><Icon name="file" /><strong>{{ t('csv') }}</strong><small>{{ t('product') }}, {{ t('margin') }}, {{ t('profit') }}</small></button></div><button class="btn primary full" :disabled="busy" @click="start"><Icon name="download" />{{ t('createExport') }}</button></template><div v-else class="job-status"><span class="badge" :class="job.status === 'completed' ? 'healthy' : 'thin'">{{ t(job.status) }}</span><progress :value="job.processed" :max="job.total || 1"></progress><p>{{ job.processed }} / {{ job.total }} {{ t('products') }}</p><a v-if="job.status === 'completed'" class="btn primary full" :href="`/api/v1/jobs/${job.id}/download`"><Icon name="download" />{{ t('download') }}</a><p v-for="e in job.errors" :key="e">{{ e }}</p></div></section></div></Teleport></template>
